export const matchEntriesInRangeQuery = (range) => {
    const c1 = new And([
        new IntegerCompare({
            key: "coordinates",
            compare: "gte",
            value: range.start1,
        }),
        new IntegerCompare({
            key: "coordinates",
            compare: "lt",
            value: range.end1,
        }),
    ]);
    // if range2 has length 0 or range 2 is equal to range 1 only make one query
    if (range.start2 === range.end2 ||
        (range.start1 === range.start2 && range.end1 === range.end2)) {
        return c1;
    }
    let ors = [
        c1,
        new And([
            new IntegerCompare({
                key: "coordinates",
                compare: "gte",
                value: range.start2,
            }),
            new IntegerCompare({
                key: "coordinates",
                compare: "lt",
                value: range.end2,
            }),
        ]),
    ];
    return new Or(ors);
};
